import subprocess

files = ['about.html', 'checklist.html', 'how-it-works.html', 'privacy.html', 
         'real-stories.html', 'resources.html', 'terms.html']

# Build correct emoji map from f377958 (clean) vs HEAD (corrupted)
emoji_map = {}
for fname in files:
    clean = subprocess.run(['git', 'show', f'f377958:{fname}'], 
        cwd='/root/.openclaw/workspace/chinahospitalsguide', capture_output=True).stdout
    corrupt = subprocess.run(['git', 'show', f'HEAD:{fname}'], 
        cwd='/root/.openclaw/workspace/chinahospitalsguide', capture_output=True).stdout

    # Find all UTF-8 encoded emojis in clean
    import re
    # Emoji regex - match multi-byte UTF-8 sequences that are emoji
    emoji_pattern = re.compile(b'[\xf0-\xf4][\x80-\xbf]{2,3}')
    clean_emoji_positions = []
    for m in emoji_pattern.finditer(clean):
        clean_emoji_positions.append((m.start(), m.group()))

    # Find all ? followed by emoji bytes in corrupt
    corrupt_emoji_positions = []
    for i in range(len(corrupt) - 2):
        if corrupt[i] == 0x3f and corrupt[i+1] >= 0x80:  # '?' followed by high byte
            # Try to decode
            for end in range(i+2, min(i+6, len(corrupt)+1)):
                try:
                    chunk = corrupt[i:end]
                    decoded = chunk.decode('utf-8')
                    # Check it's a real emoji
                    import unicodedata
                    if unicodedata.category(decoded).startswith('So'):
                        corrupt_emoji_positions.append((i, chunk, decoded))
                        break
                except:
                    break

    # Match them up by position
    for (cpos, clean_bytes), (bpos, corrupt_bytes, decoded) in zip(clean_emoji_positions, corrupt_emoji_positions):
        if corrupt_bytes not in emoji_map:
            emoji_map[corrupt_bytes] = clean_bytes

    print(f"{fname}: {len(clean_emoji_positions)} clean emojis, {len(corrupt_emoji_positions)} corrupt positions")

print(f"\nTotal unique corrupt→clean mappings: {len(emoji_map)}")
for bad, good in sorted(emoji_map.items()):
    try:
        print(f"  {bad!r} ({bad.decode('utf-8', errors='replace')}) → {good!r} ({good.decode('utf-8')})")
    except:
        print(f"  {bad!r} → {good!r}")
"}

